343: 	fnType := reflect.FuncOf([]reflect.Type{valE.Type()}, []reflect.Type{valTrue.Type()}, false)
344: 	fnVal := reflect.MakeFunc(fnType, func(args []reflect.Value) []reflect.Value {
345: 		valE.Elem().Set(args[0].Elem())
346: 		return []reflect.Value{valTrue}
347: 	})
