352: // If the any callback returns true the event loop will stop.
353: // It will enable the related domains if not enabled, and restore them after wait ends.
354: func (b *Browser) eachEvent(sessionID proto.TargetSessionID, callbacks ...interface{}) (wait func()) {
355: 	cbMap := map[string]reflect.Value{}
356: 	restores := []func(){}
357: 
358: 	for _, cb := range callbacks {
359: 		cbVal := reflect.ValueOf(cb)
360: 		eType := cbVal.Type().In(0)
361: 		name := reflect.New(eType.Elem()).Interface().(proto.Event).ProtoEvent() //nolint: forcetypeassert
362: 		cbMap[name] = cbVal
363: 
364: 		// Only enabled domains will emit events to cdp client.
365: 		// We enable the domains for the event types if it's not enabled.
366: 		// We restore the domains to their previous states after the wait ends.
367: 		domain, _ := proto.ParseMethodName(name)
368: 		if req := proto.GetType(domain + ".enable"); req != nil {
369: 			enable := reflect.New(req).Interface().(proto.Request) //nolint: forcetypeassert
370: 			restores = append(restores, b.EnableDomain(sessionID, enable))
371: 		}
372: 	}
373: 
374: 	b, cancel := b.WithCancel()
375: 	messages := b.Event()
376: 
377: 	return func() {
378: 		if messages == nil {
379: 			panic("can't use wait function twice")
380: 		}
381: 
382: 		defer func() {
383: 			cancel()
384: 			messages = nil
385: 			for _, restore := range restores {
386: 				restore()
387: 			}
388: 		}()
389: 
390: 		for msg := range messages {
391: 			if !(sessionID == "" || msg.SessionID == sessionID) {
392: 				continue
393: 			}
394: 
395: 			if cbVal, has := cbMap[msg.Method]; has {
396: 				e := reflect.New(proto.GetType(msg.Method))
397: 				msg.Load(e.Interface().(proto.Event)) //nolint: forcetypeassert
398: 				args := []reflect.Value{e}
399: 				if cbVal.Type().NumIn() == 2 {
400: 					args = append(args, reflect.ValueOf(msg.SessionID))
401: 				}
402: 				res := cbVal.Call(args)
403: 				if len(res) > 0 {
404: 					if res[0].Bool() {
405: 						return
406: 					}
407: 				}
408: 			}
409: 		}
410: 	}
411: }
