316: // Close tries to close page, running its beforeunload hooks, if has any.
317: func (p *Page) Close() error {
318: 	p.browser.targetsLock.Lock()
319: 	defer p.browser.targetsLock.Unlock()
320: 
321: 	success := true
322: 	ctx, cancel := context.WithCancel(p.ctx)
323: 	defer cancel()
324: 	messages := p.browser.Context(ctx).Event()
325: 
326: 	for {
327: 		err := proto.PageClose{}.Call(p)
328: 		if errors.Is(err, cdp.ErrNotAttachedToActivePage) {
329: 			// TODO: I don't know why chromium doesn't allow us to close a page while it's navigating.
330: 			// Looks like a bug in chromium.
331: 			utils.Sleep(0.1)
332: 			continue
333: 		} else if err != nil {
334: 			return err
335: 		}
336: 		break
337: 	}
338: 
339: 	for msg := range messages {
340: 		stop := false
341: 
342: 		destroyed := proto.TargetTargetDestroyed{}
343: 		closed := proto.PageJavascriptDialogClosed{}
344: 		if msg.Load(&destroyed) {
345: 			stop = destroyed.TargetID == p.TargetID
346: 		} else if msg.SessionID == p.SessionID && msg.Load(&closed) {
347: 			success = closed.Result
348: 			stop = !success
349: 		}
350: 
351: 		if stop {
352: 			break
353: 		}
354: 	}
355: 
356: 	if success {
357: 		p.cleanupStates()
358: 	} else {
359: 		return &PageCloseCanceledError{}
360: 	}
361: 
362: 	return nil
363: }
