384: // HandleDialog accepts or dismisses next JavaScript initiated dialog (alert, confirm, prompt, or onbeforeunload).
385: // Because modal dialog will block js, usually you have to trigger the dialog in another goroutine.
386: // For example:
387: //
388: //	wait, handle := page.MustHandleDialog()
389: //	go page.MustElement("button").MustClick()
390: //	wait()
391: //	handle(true, "")
392: func (p *Page) HandleDialog() (
393: 	wait func() *proto.PageJavascriptDialogOpening,
394: 	handle func(*proto.PageHandleJavaScriptDialog) error,
395: ) {
396: 	restore := p.EnableDomain(&proto.PageEnable{})
397: 
398: 	var e proto.PageJavascriptDialogOpening
399: 	w := p.WaitEvent(&e)
400: 
401: 	return func() *proto.PageJavascriptDialogOpening {
402: 			w()
403: 			return &e
404: 		}, func(h *proto.PageHandleJavaScriptDialog) error {
405: 			defer restore()
406: 			return h.Call(p)
407: 		}
408: }
