436: // Screenshot captures the screenshot of current page.
437: func (p *Page) Screenshot(fullPage bool, req *proto.PageCaptureScreenshot) ([]byte, error) {
438: 	if req == nil {
439: 		req = &proto.PageCaptureScreenshot{}
440: 	}
441: 	if fullPage {
442: 		metrics, err := proto.PageGetLayoutMetrics{}.Call(p)
443: 		if err != nil {
444: 			return nil, err
445: 		}
446: 
447: 		if metrics.CSSContentSize == nil {
448: 			return nil, errors.New("failed to get css content size")
449: 		}
450: 
451: 		oldView := proto.EmulationSetDeviceMetricsOverride{}
452: 		set := p.LoadState(&oldView)
453: 		view := oldView
454: 		view.Width = int(metrics.CSSContentSize.Width)
455: 		view.Height = int(metrics.CSSContentSize.Height)
456: 
457: 		err = p.SetViewport(&view)
458: 		if err != nil {
459: 			return nil, err
460: 		}
461: 
462: 		defer func() { // try to recover the viewport
463: 			if !set {
464: 				_ = proto.EmulationClearDeviceMetricsOverride{}.Call(p)
465: 				return
466: 			}
467: 
468: 			_ = p.SetViewport(&oldView)
469: 		}()
470: 	}
471: 
472: 	shot, err := req.Call(p)
473: 	if err != nil {
474: 		return nil, err
475: 	}
476: 	return shot.Data, nil
477: }
