479: // ScrollScreenshotOptions is the options for the ScrollScreenshot.
480: type ScrollScreenshotOptions struct {
481: 	// Format (optional) Image compression format (defaults to png).
482: 	Format proto.PageCaptureScreenshotFormat `json:"format,omitempty"`
483: 
484: 	// Quality (optional) Compression quality from range [0..100] (jpeg only).
485: 	Quality *int `json:"quality,omitempty"`
486: 
487: 	// FixedTop (optional) The number of pixels to skip from the top.
488: 	// It is suitable for optimizing the screenshot effect when there is a fixed
489: 	// positioning element at the top of the page.
490: 	FixedTop float64
491: 
492: 	// FixedBottom (optional) The number of pixels to skip from the bottom.
493: 	FixedBottom float64
494: 
495: 	// WaitPerScroll until no animation (default is 300ms)
496: 	WaitPerScroll time.Duration
497: }
498: 
499: // ScrollScreenshot Scroll screenshot does not adjust the size of the viewport,
500: // but achieves it by scrolling and capturing screenshots in a loop, and then stitching them together.
501: // Note that this method also has a flaw: when there are elements with fixed
502: // positioning on the page (usually header navigation components),
503: // these elements will appear repeatedly, you can set the FixedTop parameter to optimize it.
504: //
505: // Only support png and jpeg format yet, webP is not supported because no suitable processing
506: // library was found in golang.
507: func (p *Page) ScrollScreenshot(opt *ScrollScreenshotOptions) ([]byte, error) {
508: 	if opt == nil {
509: 		opt = &ScrollScreenshotOptions{}
510: 	}
511: 	if opt.WaitPerScroll == 0 {
512: 		opt.WaitPerScroll = time.Millisecond * 300
513: 	}
514: 
515: 	metrics, err := proto.PageGetLayoutMetrics{}.Call(p)
516: 	if err != nil {
517: 		return nil, err
518: 	}
519: 
520: 	if metrics.CSSContentSize == nil || metrics.CSSVisualViewport == nil {
521: 		return nil, errors.New("failed to get css content size")
522: 	}
523: 
524: 	viewpointHeight := metrics.CSSVisualViewport.ClientHeight
525: 	contentHeight := metrics.CSSContentSize.Height
526: 
527: 	var scrollTop float64
528: 	var images []utils.ImgWithBox
529: 
530: 	for {
531: 		clip := &proto.PageViewport{
532: 			X:     0,
533: 			Y:     scrollTop,
534: 			Width: metrics.CSSVisualViewport.ClientWidth,
535: 			Scale: 1,
536: 		}
537: 
538: 		scrollY := viewpointHeight - (opt.FixedTop + opt.FixedBottom)
539: 		if scrollTop+viewpointHeight > contentHeight {
540: 			clip.Height = contentHeight - scrollTop
541: 		} else {
542: 			clip.Height = scrollY
543: 			if scrollTop != 0 {
544: 				clip.Y += opt.FixedTop
545: 			}
546: 		}
547: 
548: 		req := &proto.PageCaptureScreenshot{
549: 			Format:                opt.Format,
550: 			Quality:               opt.Quality,
551: 			Clip:                  clip,
552: 			FromSurface:           false,
553: 			CaptureBeyondViewport: false,
554: 			OptimizeForSpeed:      false,
555: 		}
556: 		shot, err := req.Call(p)
557: 		if err != nil {
558: 			return nil, err
559: 		}
560: 
561: 		images = append(images, utils.ImgWithBox{Img: shot.Data})
562: 
563: 		scrollTop += scrollY
564: 		if scrollTop >= contentHeight {
565: 			break
566: 		}
567: 
568: 		err = p.Mouse.Scroll(0, scrollY, 1)
569: 		if err != nil {
570: 			return nil, fmt.Errorf("scroll error: %w", err)
571: 		}
572: 
573: 		err = p.WaitDOMStable(opt.WaitPerScroll, 0)
574: 		if err != nil {
575: 			return nil, fmt.Errorf("WaitDOMStable error: %w", err)
576: 		}
577: 	}
578: 
579: 	var imgOption *utils.ImgOption
580: 	if opt.Quality != nil {
581: 		imgOption = &utils.ImgOption{
582: 			Quality: *opt.Quality,
583: 		}
584: 	}
585: 	bs, err := utils.SplicePngVertical(images, opt.Format, imgOption)
586: 	if err != nil {
587: 		return nil, err
588: 	}
589: 
590: 	return bs, nil
591: }
