709: // WaitRequestIdle returns a wait function that waits until no request for d duration.
710: // Be careful, d is not the max wait timeout, it's the least idle time.
711: // If you want to set a timeout you can use the [Page.Timeout] function.
712: // Use the includes and excludes regexp list to filter the requests by their url.
713: func (p *Page) WaitRequestIdle(
714: 	d time.Duration,
715: 	includes, excludes []string,
716: 	excludeTypes []proto.NetworkResourceType,
717: ) func() {
718: 	defer p.tryTrace(TraceTypeWait, "request-idle")()
719: 
720: 	if excludeTypes == nil {
721: 		excludeTypes = []proto.NetworkResourceType{
722: 			proto.NetworkResourceTypeWebSocket,
723: 			proto.NetworkResourceTypeEventSource,
724: 			proto.NetworkResourceTypeMedia,
725: 			proto.NetworkResourceTypeImage,
726: 			proto.NetworkResourceTypeFont,
727: 		}
728: 	}
729: 
730: 	if len(includes) == 0 {
731: 		includes = []string{""}
732: 	}
733: 
734: 	p, cancel := p.WithCancel()
735: 	match := genRegMatcher(includes, excludes)
736: 	waitList := map[proto.NetworkRequestID]string{}
737: 	idleCounter := utils.NewIdleCounter(d)
738: 	update := p.tryTraceReq(includes, excludes)
739: 	update(nil)
740: 
741: 	checkDone := func(id proto.NetworkRequestID) {
742: 		if _, has := waitList[id]; has {
743: 			delete(waitList, id)
744: 			update(waitList)
745: 			idleCounter.Done()
746: 		}
747: 	}
748: 
749: 	wait := p.EachEvent(func(sent *proto.NetworkRequestWillBeSent) {
750: 		for _, t := range excludeTypes {
751: 			if sent.Type == t {
752: 				return
753: 			}
754: 		}
755: 
756: 		if match(sent.Request.URL) {
757: 			// Redirect will send multiple NetworkRequestWillBeSent events with the same RequestID,
758: 			// we should filter them out.
759: 			if _, has := waitList[sent.RequestID]; !has {
760: 				waitList[sent.RequestID] = sent.Request.URL
761: 				update(waitList)
762: 				idleCounter.Add()
763: 			}
764: 		}
765: 	}, func(e *proto.NetworkLoadingFinished) {
766: 		checkDone(e.RequestID)
767: 	}, func(e *proto.NetworkLoadingFailed) {
768: 		checkDone(e.RequestID)
769: 	})
770: 
771: 	return func() {
772: 		go func() {
773: 			idleCounter.Wait(p.ctx)
774: 			cancel()
775: 		}()
