152: 	if noPointerEvents.Value.Bool() {
153: 		return nil, &NoPointerEventsError{el}
154: 	}
155: 
156: 	shape, err := el.Shape()
157: 	if err != nil {
158: 		return nil, err
159: 	}
160: 
161: 	pt = shape.OnePointInside()
162: 	if pt == nil {
163: 		err = &InvisibleShapeError{el}
164: 		return
165: 	}
166: 
167: 	scroll, err := el.page.root.Context(el.ctx).Eval(`() => ({ x: window.scrollX, y: window.scrollY })`)
168: 	if err != nil {
169: 		return
170: 	}
171: 
172: 	elAtPoint, err := el.page.Context(el.ctx).ElementFromPoint(
173: 		int(pt.X)+scroll.Value.Get("x").Int(),
174: 		int(pt.Y)+scroll.Value.Get("y").Int(),
175: 	)
176: 	if err != nil {
177: 		if errors.Is(err, cdp.ErrNodeNotFoundAtPos) {
178: 			err = &InvisibleShapeError{el}
179: 		}
180: 		return
181: 	}
182: 
183: 	isParent, err := el.ContainsElement(elAtPoint)
184: 	if err != nil {
185: 		return
186: 	}
187: 
188: 	if !isParent {
189: 		err = &CoveredError{elAtPoint}
190: 	}
191: 	return
192: }
