516: // WaitStable waits until no shape or position change for d duration.
517: // Be careful, d is not the max wait timeout, it's the least stable time.
518: // If you want to set a timeout you can use the [Element.Timeout] function.
519: func (el *Element) WaitStable(d time.Duration) error {
520: 	err := el.WaitVisible()
521: 	if err != nil {
522: 		return err
523: 	}
524: 
525: 	defer el.tryTrace(TraceTypeWait, "stable")()
526: 
527: 	shape, err := el.Shape()
528: 	if err != nil {
529: 		return err
530: 	}
531: 
532: 	t := time.NewTicker(d)
533: 	defer t.Stop()
534: 
535: 	for {
536: 		select {
537: 		case <-t.C:
538: 		case <-el.ctx.Done():
539: 			return el.ctx.Err()
540: 		}
541: 		current, err := el.Shape()
542: 		if err != nil {
543: 			return err
544: 		}
545: 		if reflect.DeepEqual(shape, current) {
546: 			break
547: 		}
548: 		shape = current
549: 	}
550: 	return nil
551: }
