557: 	err := el.WaitVisible()
558: 	if err != nil {
559: 		return err
560: 	}
561: 
562: 	defer el.tryTrace(TraceTypeWait, "stable RAF")()
563: 
564: 	var shape *proto.DOMGetContentQuadsResult
565: 	page := el.page.Context(el.ctx)
566: 
567: 	for {
568: 		err = page.WaitRepaint()
569: 		if err != nil {
570: 			return err
571: 		}
572: 
573: 		current, err := el.Shape()
574: 		if err != nil {
575: 			return err
576: 		}
577: 		if reflect.DeepEqual(shape, current) {
578: 			break
579: 		}
580: 		shape = current
581: 	}
582: 	return nil
