31: // Connect to browser.
32: func (ws *WebSocket) Connect(ctx context.Context, wsURL string, header http.Header) error {
33: 	if ws.conn != nil {
34: 		panic("duplicated connection: " + wsURL)
35: 	}
36: 
37: 	u, err := url.Parse(wsURL)
38: 	if err != nil {
39: 		return err
40: 	}
41: 
